package scenario

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// Event represents a single scenario event
// Only limited fields are supported per docs/events.md
// weight defaults to 1 if not set

type Event struct {
	Method  string            `json:"method"`
	Path    string            `json:"path"`
	Headers map[string]string `json:"headers,omitempty"`
	Body    string            `json:"body,omitempty"`
	Weight  int               `json:"weight,omitempty"`
}

// weightedPool helps selecting events by weight
// We implement prefix sums for efficient selection if needed in future
// For now we just build expanded slice according to weight for simplicity

type weightedPool struct {
	events []Event
}

// newWeightedPool creates a weightedPool from given events, expanding entries by weight
func newWeightedPool(events []Event) *weightedPool {
	var expanded []Event
	for _, ev := range events {
		w := ev.Weight
		if w <= 0 {
			w = 1
		}
		for i := 0; i < w; i++ {
			expanded = append(expanded, ev)
		}
	}
	return &weightedPool{events: expanded}
}

// Events returns slice of events expanded by weight

func (p *weightedPool) Events() []Event {
	return p.events
}

// LoadScenario loads scenario events from file by scenarioId
// Loads file from ./data/scenarios/<scenarioId>.jsonl
// Parses JSONL lines to Event, supports method,path,headers,body,weight
// Returns expanded events by weight or error

func LoadScenario(scenarioId string) ([]Event, error) {
	const scenariosDir = "./data/scenarios"
	path := filepath.Join(scenariosDir, scenarioId+".jsonl")

	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("failed to open scenario file: %w", err)
	}
	defer file.Close()

	var events []Event
	rdr := bufio.NewReader(file)

	lineNum := 0
	for {
		line, err := rdr.ReadString('\n')
		if err != nil && !errors.Is(err, io.EOF) {
			return nil, fmt.Errorf("read error: %w", err)
		}
		line = strings.TrimSpace(line)
		if line != "" {
			var ev map[string]interface{}
			if err := json.Unmarshal([]byte(line), &ev); err != nil {
				return nil, fmt.Errorf("json parse error line %d: %w", lineNum+1, err)
			}

			// Validate type field to be "http" (from docs/events.md example)
			typeVal, ok := ev["type"]
			if !ok || typeVal != "http" {
				return nil, fmt.Errorf("invalid or missing event type at line %d", lineNum+1)
			}

			// Parse fields with basic type assertions
			method, _ := ev["method"].(string)
			path, _ := ev["path"].(string)

			// headers is optional map[string]string
			headersMap := make(map[string]string)
			if rawHeaders, ok := ev["headers"].(map[string]interface{}); ok {
				for k, v := range rawHeaders {
					if vs, ok := v.(string); ok {
						headersMap[k] = vs
					}
				}
			}

			// body can be string
			body := ""
			if b, ok := ev["body"].(string); ok {
				body = b
			}

			// weight integer >0 or default 1
			weight := 1
			if w, ok := ev["weight"].(float64); ok {
				weight = int(w)
				if weight < 1 {
					weight = 1
				}
			}

			events = append(events, Event{
				Method:  method,
				Path:    path,
				Headers: headersMap,
				Body:    body,
				Weight:  weight,
			})
		}

		lineNum++
		if errors.Is(err, io.EOF) {
			break
		}
	}

	if len(events) == 0 {
		return nil, errors.New("no valid events found")
	}

	// Build weighted pool to expand by weight
	pool := newWeightedPool(events)
	return pool.Events(), nil
}

// Extra: helper function for safer scenarioId validation (not part of spec but useful for tests)
//
// ValidScenarioID checks if scenarioId matches safe pattern

func ValidScenarioID(id string) bool {
	if id == "" {
		return false
	}
	for _, r := range id {
		if !(r >= 'A' && r <= 'Z') && !(r >= 'a' && r <= 'z') && !(r >= '0' && r <= '9') && r != '_' && r != '-' {
			return false
		}
	}
	return true
}

package scenario

import (
	"os"
	"path/filepath"
	"testing"
)

func TestLoadScenario_ValidSimple(t *testing.T) {
	tmpDir := "./data/scenarios"
	os.MkdirAll(tmpDir, 0o755)
	filename := filepath.Join(tmpDir, "testscenario.jsonl")
	content := `{"ts":"2021-01-01T00:00:00Z","type":"http","method":"GET","path":"/api/foo","weight":2}
{"ts":"2021-01-01T00:00:01Z","type":"http","method":"POST","path":"/api/bar","weight":3}`
	err := os.WriteFile(filename, []byte(content), 0o644)
	if err != nil {
		t.Fatalf("failed to write scenario file: %v", err)
	}
	defer os.Remove(filename)

	events, err := LoadScenario("testscenario")
	if err != nil {
		t.Fatalf("LoadScenario error: %v", err)
	}

	// Expect expanded by weight: 2 + 3 = 5
	if len(events) != 5 {
		t.Fatalf("expected 5 events expanded by weight, got %d", len(events))
	}

	// Check first 2 events method GET
	for i := 0; i < 2; i++ {
		if events[i].Method != "GET" {
			t.Errorf("expected method GET at index %d, got %s", i, events[i].Method)
		}
	}

	// Check next 3 events method POST
	for i := 2; i < 5; i++ {
		if events[i].Method != "POST" {
			t.Errorf("expected method POST at index %d, got %s", i, events[i].Method)
		}
	}
}

func TestLoadScenario_InvalidJSON(t *testing.T) {
	tmpDir := "./data/scenarios"
	os.MkdirAll(tmpDir, 0o755)
	filename := filepath.Join(tmpDir, "invalid.jsonl")
	content := `invalid json line`
	_ = os.WriteFile(filename, []byte(content), 0o644)
	defer os.Remove(filename)

	_, err := LoadScenario("invalid")
	if err == nil {
		t.Fatal("expected error for invalid json")
	}
}

func TestLoadScenario_Empty(t *testing.T) {
	tmpDir := "./data/scenarios"
	os.MkdirAll(tmpDir, 0o755)
	filename := filepath.Join(tmpDir, "empty.jsonl")
	content := `


` // empty lines
	_ = os.WriteFile(filename, []byte(content), 0o644)
	defer os.Remove(filename)

	_, err := LoadScenario("empty")
	if err == nil {
		t.Fatal("expected error for empty events")
	}
}

func TestLoadScenario_MissingFile(t *testing.T) {
	_, err := LoadScenario("notexists")
	if err == nil {
		t.Fatal("expected error for missing file")
	}
}

func TestValidScenarioID(t *testing.T) {
	valids := []string{"abc123", "ABC_def-456"}
	invalids := []string{"abc def", "abc/def", "", "abc$", "abc@"}

	for _, v := range valids {
		if !ValidScenarioID(v) {
			t.Errorf("expected valid but got invalid for %s", v)
		}
	}

	for _, v := range invalids {
		if ValidScenarioID(v) {
			t.Errorf("expected invalid but got valid for %s", v)
		}
	}
}
